26	/**
27	 * Populates the read-only {@code namesakeCount} on an owner response: the number of owners
28	 * registered before this one (lower id) that share the same first and last name, compared
29	 * case-insensitively. It is derived on the way out, so it never affects storage or the request.
30	 */
31	@Aspect
32	@Component
33	public class OwnerNamesakeCountAdvice {
34	
35	    private final ClinicService clinicService;
36	
37	    public OwnerNamesakeCountAdvice(ClinicService clinicService) {
38	        this.clinicService = clinicService;
39	    }
40	
41	    @AfterReturning(pointcut = "execution(* org.springframework.samples.petclinic.rest.controller.v1."
42	        + "OwnerRestControllerV1.addOwner(..)) || execution(* org.springframework.samples.petclinic.rest."
43	        + "controller.v1.OwnerRestControllerV1.getOwner(..))", returning = "response")
44	    public void addNamesakeCount(ResponseEntity<?> response) {
45	        Object body = response == null ? null : response.getBody();
46	        if (!(body instanceof OwnerDto owner) || owner.getId() == null) {
47	            return;
48	        }
49	        int namesakeCount = (int) clinicService.findAllOwners().stream()
50	            .filter(other -> other.getId() != null && other.getId() < owner.getId()
51	                && matches(owner.getFirstName(), other.getFirstName())
52	                && matches(owner.getLastName(), other.getLastName()))
53	            .count();
54	        owner.setNamesakeCount(namesakeCount);
55	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
56	        owner.setMembershipLevel(Math.min(3, 1 + (hasEmail ? 1 : 0) + (namesakeCount == 0 ? 1 : 0)));
57	    }
58	
59	    private static boolean matches(String a, String b) {
60	        return a != null && a.equalsIgnoreCase(b);
61	    }
62	}
