28	/**
29	 * Populates the read-only {@code bulkSignupWarning} on an owner response: {@code true} once more
30	 * than 80 owners have already been created today (by their {@code registrationDate}), otherwise
31	 * {@code false}. Derived on the way out, so it never affects storage or the request.
32	 */
33	@Aspect
34	@Component
35	public class OwnerBulkSignupWarningAdvice {
36	
37	    private static final int BULK_THRESHOLD = 80;
38	
39	    private final ClinicService clinicService;
40	
41	    public OwnerBulkSignupWarningAdvice(ClinicService clinicService) {
42	        this.clinicService = clinicService;
43	    }
44	
45	    @AfterReturning(pointcut = "execution(* org.springframework.samples.petclinic.rest.controller.v1."
46	        + "OwnerRestControllerV1.addOwner(..)) || execution(* org.springframework.samples.petclinic.rest."
47	        + "controller.v1.OwnerRestControllerV1.getOwner(..))", returning = "response")
48	    public void addBulkSignupWarning(ResponseEntity<?> response) {
49	        Object body = response == null ? null : response.getBody();
50	        if (!(body instanceof OwnerDto owner)) {
51	            return;
52	        }
53	        LocalDate today = BusinessDay.onOrNextBusinessDay(LocalDate.now());
54	        long createdToday = clinicService.findAllOwners().stream()
55	            .filter(existing -> today.equals(existing.getRegistrationDate()))
56	            .count();
57	        owner.setBulkSignupWarning(createdToday > BULK_THRESHOLD);
