18	
19	/**
20	 * Converts a raw telephone into E.164 form. A leading '+' and country code are kept as given;
21	 * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
22	 * digits. Spaces, dashes and brackets are stripped, and the result must carry 8 to 15 digits after
23	 * the '+'. The national-number length is also checked against the country code ('+61' requires 9
24	 * national digits, '+1' requires 10). Returns {@code null} when no valid E.164 number can be formed.
25	 */
26	final class E164Telephone {
27	
28	    private E164Telephone() {
29	    }
30	
31	    static String toE164(String raw) {
32	        String cleaned = raw.replaceAll("[ ()\\-]", "");
33	        String digits = cleaned.startsWith("+") ? cleaned.substring(1)
34	            : "61" + (cleaned.startsWith("0") ? cleaned.substring(1) : cleaned);
35	        return digits.matches("\\d{8,15}") && nationalLengthOk(digits) ? "+" + digits : null;
36	    }
37	
38	    /** True unless the national digits are the wrong length for a known country code. */
39	    private static boolean nationalLengthOk(String digits) {
40	        if (digits.startsWith("61")) {
41	            return digits.length() - 2 == 9;
42	        }
43	        if (digits.startsWith("1")) {
44	            return digits.length() - 1 == 10;
45	        }
46	        return true;
47	    }
48	}
