3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Builds an owner's {@code customerCode} in the format {@code '<CITY3>-<LAST3>-<NNNN>'}:
9	 * the upper-cased first three letters of the city, the first three of the last name, and a
10	 * per-city 4-digit sequence (one more than the owners already registered in that city).
11	 */
12	final class CustomerCode {
13	
14	    private CustomerCode() {
15	    }
16	
17	    static String of(Owner owner, Collection<Owner> existing) {
18	        long inCity = existing.stream()
19	            .filter(o -> owner.getCity().equalsIgnoreCase(o.getCity()))
20	            .count();
21	        return String.format("%s-%s-%04d", head(owner.getCity()), head(owner.getLastName()), inCity + 1);
22	    }
23	
24	    private static String head(String value) {
25	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
26	    }
27	}
