18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	import java.time.temporal.TemporalAdjusters;
21	
22	/**
23	 * Rolls a date onto a business day: a Saturday or Sunday is moved forward to the next Monday,
24	 * any weekday is returned unchanged.
25	 */
26	public final class BusinessDay {
27	
28	    private BusinessDay() {
29	    }
30	
31	    public static LocalDate onOrNextBusinessDay(LocalDate date) {
32	        DayOfWeek day = date.getDayOfWeek();
33	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
34	            return date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
35	        }
36	        return date;
37	    }
38	}
